const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];
const falta = ["ERPNEXT_DOMAIN", "ERPNEXT_API_KEY", "ERPNEXT_API_SECRET"].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO_RITMO: variáveis ausentes no ambiente do Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO_RITMO');
return [{ json: { ok: true } }];

const lista = ($input.first().json.data) || [];
const me = lista.find(r => r.provedor === 'melhorenvio' && r.status === 'conectado') || null;
const pendencias = [
  { campo: 'ia', codigo: 'PENDENTE_FONTE_DE_DADOS', detalhe: 'Não há, nos arquivos do projeto, fonte existente de requisições de IA por dia (Lyra Central não expõe endpoint de uso documentado).' },
  { campo: 'frete', codigo: 'PENDENTE_FONTE_DE_DADOS', detalhe: 'Não há fonte existente de fretes emitidos por semana.' },
  { campo: 'freteVolume', codigo: 'PENDENTE_FONTE_DE_DADOS', detalhe: 'Não há fonte existente de fretes emitidos no mês.' }
];
const parcial = {};
if (me && me.saldo) { parcial.freteSaldo = me.saldo; parcial.freteSaldo_fonte = 'Synapse Credencial Externa (melhorenvio).saldo — cache'; parcial.freteSaldo_cache_atualizado_em = me.cache_atualizado_em || null; }
else pendencias.push({ campo: 'freteSaldo', codigo: 'PENDENTE_FONTE_DE_DADOS', detalhe: me ? 'Cache de saldo do Melhor Envio vazio no Ritmo.' : 'Melhor Envio não está conectado no Ritmo.' });
const m = 'PENDENTE_FONTE_DE_DADOS: ' + pendencias.map(p => p.campo).join(', ');
return [{ json: { status: 501, body: { sucesso: false, status: 'PENDENTE_FONTE_DE_DADOS', erro: m, message: m, pendencias, parcial } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao consultar credenciais no Ritmo" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "ritmo" } } }];
